"""Real MP4 sampling tests: use actual generated bytes, not illustrative metadata."""
import json
import shutil
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))
import studio_regia_real_mp4_v1 as audit


@unittest.skipUnless(shutil.which("ffmpeg") and shutil.which("ffprobe"), "FFmpeg not installed")
class RegiaRealMP4Tests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.folder = Path(self.tmp.name)

    def make_mp4(self, source="color=c=blue:s=320x568:r=8", seconds=7):
        path = self.folder / "real_video.mp4"
        subprocess.run(
            ["ffmpeg", "-v", "error", "-nostdin", "-f", "lavfi", "-i", source,
             "-t", str(seconds), "-c:v", "mpeg4", "-q:v", "8",
             "-y", str(path)],
            capture_output=True, check=True, timeout=50,
        )
        return path

    def test_static_video_generates_actual_frame_evidence_not_approval(self):
        video = self.make_mp4(seconds=8)
        before = audit.digest(video)
        report = audit.analyze(video, self.folder / "audit", sample_cap=24)
        self.assertEqual(report["source"]["sha256"], before)
        self.assertEqual(audit.digest(video), before)
        self.assertTrue(report["potential_still_intervals"])
        self.assertIn("POSSIBLE_VISUAL_STALL", [x["code"] for x in report["warnings"]])
        self.assertTrue((self.folder / "audit" / report["contact_sheet"]).is_file())
        self.assertTrue((self.folder / "audit" / "REGIA_REAL_MP4_V1.json").is_file())
        self.assertFalse(report["artistically_approved"])
        self.assertFalse(report["published"])
        self.assertFalse(report["final_master"])
        self.assertEqual(report["paid_calls"], 0)

    def test_genuinely_moving_video_is_not_classified_as_full_freeze(self):
        video = self.make_mp4("testsrc2=s=320x568:r=8", seconds=7)
        report = audit.analyze(video, self.folder / "moving", sample_cap=24)
        self.assertTrue(report["sampling"]["frames_checked"] >= 7)
        self.assertFalse(any(s["sampled_span_s"] >= 5 for s in report["potential_still_intervals"]))
        self.assertEqual(report["status"], "needs_actual_visual_and_audio_review")

    def test_missing_video_fails_closed(self):
        with self.assertRaises(ValueError):
            audit.analyze(self.folder / "not-present.mp4", self.folder / "missing")

    def test_invalid_sample_limit_fails_closed(self):
        video = self.make_mp4(seconds=2)
        for invalid in (0, 1000, True, "24"):
            with self.subTest(invalid=invalid):
                with self.assertRaises(ValueError):
                    audit.analyze(video, self.folder / "bad", sample_cap=invalid)

    def test_report_contains_real_source_duration(self):
        video = self.make_mp4(seconds=4)
        report = audit.analyze(video, self.folder / "duration", sample_cap=12)
        self.assertGreater(report["source"]["duration_s"], 3.5)
        self.assertLess(report["source"]["duration_s"], 4.5)
        self.assertGreater(report["sampling"]["frames_checked"], 3)


if __name__ == "__main__":
    unittest.main()
